46	export async function proxy(request: NextRequest) {
47	  const { supabaseResponse, user } = await updateSession(request);
48	
49	  const { pathname } = request.nextUrl;
50	
51	  // Block unauthenticated access to protected + admin routes
52	  if ((isProtectedPath(pathname) || isAdminPath(pathname)) && !user) {
53	    const redirectUrl = request.nextUrl.clone();
54	    redirectUrl.pathname = "/auth";
55	    // Only set ?next= for non-root paths — Auth.tsx defaults to "/" already
56	    if (pathname !== "/") {
57	      redirectUrl.searchParams.set("next", pathname);
58	    }
59	    const redirectResponse = NextResponse.redirect(redirectUrl);
60	    // Forward any refreshed auth cookies from updateSession onto the
61	    // redirect response so a just-expired session doesn't force a
62	    // full re-login on the next request.
63	    supabaseResponse.cookies.getAll().forEach((cookie) => {
64	      redirectResponse.cookies.set(cookie);
65	    });
66	    return redirectResponse;
67	  }
68	
69	  return supabaseResponse;
70	}
